import React from'react';
import{Link}from'react-router-dom';

export default function Footer(){
return(
<>
<style>{`
@keyframes rgbGlow{0%{filter:hue-rotate(0deg)}100%{filter:hue-rotate(360deg)}}
@keyframes floatLogo{0%,100%{transform:translateY(0)}50%{transform:translateY(-4px)}}
@keyframes pulseGlow{0%,100%{box-shadow:0 0 0 rgba(0,210,196,0)}50%{box-shadow:0 0 24px rgba(0,210,196,.18)}}
.footer-social:hover{background:#00D2C4!important;color:#000!important;transform:translateY(-4px) scale(1.08);box-shadow:0 0 18px rgba(0,210,196,.45)}
.footer-link:hover{color:#00D2C4!important;padding-left:7px}
.footer-course:hover{color:#00D2C4!important;padding-left:7px}
.footer-contact:hover{color:#00D2C4!important}
.footer-logo{animation:floatLogo 4s ease-in-out infinite}
.footer-cta{animation:pulseGlow 3s ease-in-out infinite}
@media(max-width:800px){
.footer-main-grid{grid-template-columns:1fr 1fr!important}
.footer-brand{grid-column:span 2!important}
}
@media(max-width:520px){
.footer-main-grid{grid-template-columns:1fr!important}
.footer-brand{grid-column:span 1!important}
.footer-bottom-row{align-items:flex-start!important;text-align:left!important}
.footer-socials{justify-content:flex-start!important}
}
`}</style>
<footer style={{background:'linear-gradient(135deg,#020812 0%,#04121c 45%,#062a2b 100%)',color:'#fff',borderTop:'1px solid rgba(0,210,196,.16)',padding:'72px 28px 32px',fontFamily:'Arial,sans-serif',position:'relative',overflow:'hidden'}}>
<div style={{position:'absolute',width:'420px',height:'420px',borderRadius:'50%',background:'rgba(0,210,196,.05)',filter:'blur(80px)',right:'-180px',top:'-180px',pointerEvents:'none'}}></div>
<div style={{position:'absolute',width:'300px',height:'300px',borderRadius:'50%',background:'rgba(121,40,202,.04)',filter:'blur(70px)',left:'-150px',bottom:'-150px',pointerEvents:'none'}}></div>
<div className="footer-main-grid" style={{maxWidth:'1250px',margin:'0 auto',display:'grid',gridTemplateColumns:'2fr 1fr 1fr 1.4fr',gap:'55px',marginBottom:'55px',position:'relative',zIndex:1}}>
<div className="footer-brand" style={{gridColumn:'span 1'}}>
<Link to="/" style={{display:'inline-flex',alignItems:'center',gap:'15px',textDecoration:'none',marginBottom:'22px'}}>
<div className="footer-logo" style={{width:'60px',height:'60px',borderRadius:'15px',background:'linear-gradient(135deg,#00D2C4,#ff007f,#7928ca,#0070f3)',backgroundSize:'300% 300%',display:'flex',alignItems:'center',justifyContent:'center',padding:'2px',boxShadow:'0 5px 20px rgba(0,210,196,.3)'}}>
<div style={{width:'100%',height:'100%',background:'#040914',borderRadius:'13px',display:'flex',alignItems:'center',justifyContent:'center',overflow:'hidden',position:'relative'}}>
<img src="/assets/logo.png" alt="Vighnavi Academy Logo" onError={e=>e.currentTarget.style.display='none'} style={{width:'100%',height:'100%',objectFit:'cover'}}/>
<span style={{position:'absolute',fontSize:'17px',fontWeight:'800',color:'#00D2C4'}}>VA</span>
</div>
</div>
<div>
<div style={{fontSize:'25px',fontWeight:'800',letterSpacing:'.5px',lineHeight:1.05,color:'#fff'}}>Vighnavi Academy</div>
<div style={{fontSize:'11px',color:'#00D2C4',marginTop:'5px',letterSpacing:'1.5px',fontWeight:'600'}}>LEARN • BUILD • GROW</div>
</div>
</Link>
